//! Circuit seams and field codec for noir-zk.
//!
//! Every circuit is compiled for BN254, so the field is fixed to [`Field`]
//! (`ark_bn254::Fr`). Circuit types and
//! registries are generated by `noir-zk-codegen`; proving and verification
//! live in `noir-zk-backend`.

pub mod artifacts;
pub mod codec;
pub mod error;
pub mod fold;
pub mod pipeline;
pub mod registry;
pub mod tree;
pub mod zk;

pub use artifacts::{Artifacts, Merged, VkPath};
pub use codec::{from_fields, FieldElement, FieldEncode, FieldReader, FromFields};
pub use error::Error;
pub use fold::{
    App, AppDispatch, AppStep, AppVisitor, Kernel, KernelInputs, StepInputs, VkInput, Wrapped,
};
pub use pipeline::{
    Accepts, BindSpec, DeploymentEntry, FamilyEntry, FamilyRef, Layout, Link, LinkSpec, Next,
    NoLink, PipelineEntry, PositionEntry, Selected, StepFamily,
};
pub use registry::{Library, RegistryEntry, Status};
pub use zk::{
    ChonkRole, Circuit, CircuitId, Field, Honk, Oracle, ProofGenerator, ProofSystem, ProofVerifier,
};
